const results = [];
for (const item of $input.all()) {
  const text = (item.json.output || "Sorry, I couldn't generate a response. Please try again.").toString();
  const chunkSize = 4000;
  if (text.length === 0) {
    results.push({ json: { output: "Sorry, I couldn't generate a response. Please try again." } });
    continue;
  }
  for (let i = 0; i < text.length; i += chunkSize) {
    results.push({ json: { output: text.slice(i, i + chunkSize) } });
  }
}
return results;
